// DefectDojo Notification Webhook payload. Field names below are a
// best-effort guess (docs.defectdojo.com describes the shape but not this
// deployment's exact version) — check the first real delivery in this
// node's output (n8n execution history) and adjust the paths here if
// test_id/product_name come back empty.
const body = $json.body ?? $json;
const test = body.test ?? body.data?.test ?? {};
return {
  json: {
    event: body.event ?? '',
    test_id: test.id ?? test.test_id ?? body.test_id ?? null,
    product_name: test.engagement?.product?.name ?? body.product?.name ?? ''
  }
};

// One n8n item per finding from this scan, skipping anything we already
// triaged on a previous (re-)import — the webhook fires per scan, not per
// finding, so re-imports of the same test would otherwise re-triage
// everything every time. Deliberately Run Once for All Items — this is
// the one node that needs to see the whole findings array at once to
// split it into items; every Code node after it is per-item.
const results = $input.first().json.results ?? $input.first().json.body?.results ?? [];
return results
  .filter(f => !(f.tags || []).includes('llm-triaged'))
  .map(f => ({ json: f }));

const f = $json;
const prompt = `You are a security triage assistant reviewing one finding from an automated SAST/secret-detection scan.

Title: ${f.title}
Current severity: ${f.severity}
CWE: ${f.cwe || 'n/a'}
File: ${f.file_path || 'n/a'}:${f.line || ''}
Component: ${f.component_name || 'n/a'} ${f.component_version || ''}
Description: ${(f.description || '').slice(0, 1500)}

Assess whether the severity is correct for this context, and whether it's urgent enough to open a tracked issue right now instead of waiting for normal triage.

Reply with ONLY a JSON object, no other text, no markdown fences:
{"severity": "Critical|High|Medium|Low|Info", "reasoning": "2-3 sentences in Russian explaining the assessment", "create_issue": true|false}`;
return { json: { ...f, prompt } };

const finding = $('Build Prompt').item.json;
let verdict;
try {
  verdict = JSON.parse($json.message.content);
  if (!verdict.severity || !verdict.reasoning) throw new Error('missing fields');
} catch (e) {
  verdict = {
    severity: finding.severity,
    reasoning: 'Не удалось разобрать ответ LLM как JSON — нужна ручная проверка. Сырой ответ: ' + JSON.stringify($json).slice(0, 300),
    create_issue: false
  };
}
return { json: { ...finding, verdict } };

// Заполнить своим маппингом: имя продукта в DefectDojo -> numeric ID проекта в GitLab
// (ID проекта — на странице проекта в GitLab, под названием, "Project ID: ...").
const PRODUCT_TO_PROJECT = {
  'usta_tap': 0 // <-- заменить 0 на реальный ID
};
const productName = $('Get Test ID').item.json.product_name;
const projectId = PRODUCT_TO_PROJECT[productName];
if (!projectId) {
  throw new Error(`Нет GitLab-проекта для продукта DefectDojo "${productName}" — добавь в PRODUCT_TO_PROJECT в этой ноде.`);
}
// $json здесь — ответ ноды Add Note (создание заметки), не находка с
// вердиктом: Critical? стоит после Add Note в цепочке, и HTTP Request
// подменяет $json своим ответом. Нужные поля — явно из Parse Verdict.
return { json: { ...$('Parse Verdict').item.json, gitlab_project_id: projectId } };
